import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c2_blocks.1_k12.npy')); b=-1.6648
A=[np.radians(67.18593453),np.radians(-134.66928719)]
xi=torch.tensor(np.load('xi_sim.npy')); c=torch.tensor(np.load('c_sim.npy')); tgt=np.load('tgt.npy'); a0=np.load('a0.npy'); N=len(c)
thc=np.polyval(A,c.numpy())
def run(dv,lo,hi,thr):
    x=xi.clone()
    for k in range(20):
        t=torch.full((N,),1-k/20)
        with torch.no_grad(): v,a=net.velocity(x,t,c,("blocks.1",),count=False)
        if lo<=k<hi:
            f=((a["blocks.1"]@w+b)>thr).float()
            v=v+f[:,None]*torch.tensor(dv,dtype=torch.float32)
        x=x-v/20
    return x.numpy()
def ev(a1):
    ang1=np.arctan2(a1[:,1],a1[:,0]); d1=np.angle(np.exp(1j*(ang1-thc)))
    still=(np.abs(d1)<np.radians(22.5))&(np.linalg.norm(a1,axis=1)>1.5)
    mv=np.linalg.norm(a1-a0,axis=1)>0.3; rr=np.linalg.norm(a1,axis=1); off=(rr<2)|(rr>3.6)
    return still[tgt].mean().round(3),mv[~tgt].mean().round(3),still[~tgt].mean().round(3),(off.mean()-((np.linalg.norm(a0,axis=1)<2)|(np.linalg.norm(a0,axis=1)>3.6)).mean()).round(3)
for thr in [0,1,2]:
  for lo,hi in [(4,12),(6,12),(6,14)]:
    for ad in [180,225,250]:
      for mag in [12,20]:
        dv=mag*np.array([np.cos(np.radians(ad)),np.sin(np.radians(ad))])
        print(thr,lo,hi,ad,mag,'still/drift/newbad/offrise',ev(run(dv,lo,hi,thr)))

