import numpy as np, torch, model
net = model.load()
xi=np.load('cal_xi.npy'); c=np.load('cal_c.npy'); a0=np.load('cal_a.npy')
wr=torch.tensor(np.load('det_w.npy')); br=float(np.load('det_b.npy'))
def lab(a):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); d=(ang-(5+50*c)+180)%360-180
    return d,(d>-22)&(d<27)
d0,y0=lab(a0)
st={'k':0}
cfg={}
def hook(m,inp,out):
    k=st['k']; st['k']+=1
    oa=inp[0]; 
    if not (cfg['LO']<=k<cfg['HI']): return out
    f=((oa@wr+br)>cfg['thr']).float()[:,None]
    x=cfg['x']()
    return out+f*cfg['push'](x)
net.out.register_forward_hook(hook)
# capture x: pre-hook on top-level
cur={}
def pre(m,args,kwargs=None):
    cur['x']=args[0]
net.register_forward_pre_hook(pre)
cfg['x']=lambda: cur['x']
def run(name,push,LO=8,HI=12,thr=1.0):
    cfg.update(push=push,LO=LO,HI=HI,thr=thr); st['k']=0
    a=model.decode(net,xi,c); a=np.asarray(a[0] if isinstance(a,tuple) else a)
    d,y=lab(a); mv=np.linalg.norm(a-a0,axis=1)>0.36
    r=np.linalg.norm(a,axis=1)
    h,_=np.histogram(d[y0&~y],bins=18,range=(-90,90))
    print(name,LO,HI,thr,'calls',st['k'],'target',y.mean().round(4),'drift nontarget',mv[~y0].mean().round(4),'rescued r mean',r[y0&~y].mean().round(2),'hist',h)
